# Critique expansion (patches): GU tail, gynae, H&N, CNS, haematology, skin, sarcoma, RT, supportive.
PATCH = {}
def c(name, critique, exc=None):
    PATCH[name] = {"critique": critique}
    if exc: PATCH[name]["exclusion"] = exc

c("NIAGARA", "Perioperative durvalumab with gem-cis improves EFS and OS in cisplatin-eligible MIBC. Because durvalumab was given both before and after surgery, the contribution of each phase cannot be separated, and only cisplatin-eligible patients were studied.")
c("CheckMate 274", "Adjuvant nivolumab improves DFS in high-risk MIUC after surgery. OS data are immature, and the benefit in upper-tract tumours and PD-L1-negative disease is less certain.")
c("EV-302", "EV-pembro roughly doubles OS over platinum chemotherapy in first-line advanced urothelial cancer — a landmark shift. Rash, neuropathy and hyperglycaemia require monitoring, and cost is a major barrier in India.")
c("CheckMate 214", "Nivo-ipi gives durable long-term OS benefit in intermediate/poor-risk ccRCC, with a plateau of long-term responders. In favourable-risk disease, sunitinib did as well, and immune toxicity needs experienced management.")
c("KEYNOTE-426 / CLEAR / CheckMate 9ER", "IO-TKI combinations improve OS over sunitinib in advanced ccRCC and achieve high response rates. TKI toxicity requires dose management, and long-term durability vs nivo-ipi is still debated.")
c("KEYNOTE-564", "Adjuvant pembrolizumab improves DFS and OS in high-risk ccRCC after nephrectomy. Many patients are cured by surgery alone and are exposed to immune toxicity without benefit.")
c("CARMENA", "Showed sunitinib alone is non-inferior to cytoreductive nephrectomy followed by sunitinib in intermediate/poor-risk mRCC. Poor accrual and a high-risk population limit applicability to the IO era.")
c("THOR", "Erdafitinib improves OS in FGFR-altered UC after prior therapy, supporting routine FGFR testing. Hyperphosphataemia, nail and ocular toxicity need monitoring.")
c("GOG 111 / OV-10", "Established platinum-paclitaxel as the standard first-line chemotherapy for advanced ovarian cancer. Carboplatin later replaced cisplatin with similar efficacy and less toxicity (GOG 158).")
c("JGOG 3016", "Dose-dense weekly paclitaxel improved OS in Japanese patients, but ICON8 and GOG 262 did not confirm benefit in Western populations. It remains an option, especially where 3-weekly regimens are poorly tolerated.")
c("EORTC 55971 / CHORUS", "NACT followed by interval debulking is non-inferior to primary surgery for stage IIIC–IV ovarian cancer, with less morbidity. Low complete resection rates in primary surgery arms have been criticised; TRUST may refine this.")
c("OVHIPEC-1", "HIPEC at interval debulking improved OS and RFS. The trial was open-label and small, and HIPEC requires expertise, so it is not universally adopted.")
c("SOLO-1", "Olaparib maintenance gives a large, durable PFS and OS benefit in BRCA-mutated ovarian cancer, with many patients long-term disease-free. It makes BRCA testing at diagnosis mandatory.")
c("PAOLA-1", "Olaparib with bevacizumab improves PFS and OS in HRD-positive advanced ovarian cancer. Little benefit in HRD-negative tumours means HRD testing is needed.")
c("PRIMA", "Niraparib improves PFS in advanced ovarian cancer across biomarker groups, but final OS showed no benefit. Thrombocytopenia requires weight-based dosing.")
c("ICON7 / GOG 218", "Bevacizumab improves PFS in advanced ovarian cancer, with OS benefit only in high-risk subgroups. Cost and hypertension limit use in India.")
c("MIRASOL", "Mirvetuximab improves OS in FRα-high platinum-resistant ovarian cancer — a rare positive trial in this setting. Ocular toxicity (keratopathy, blurred vision) requires eye care.")
c("PORTEC-1/2", "Vaginal brachytherapy gives similar vaginal control to pelvic EBRT with less toxicity in high-intermediate-risk endometrial cancer. Molecular classification (PORTEC-4a) now refines who needs any RT.")
c("PORTEC-3", "ChemoRT improves OS in high-risk endometrial cancer, especially serous histology and stage III. Long-term neuropathy and toxicity are significant, and molecular subgroup analysis shows p53-abnormal tumours benefit most.")
c("GOG 258", "ChemoRT did not improve RFS over chemotherapy alone in stage III–IVA endometrial cancer, but reduced pelvic and vaginal recurrence. Combined with PORTEC-3, it supports chemotherapy as the backbone with selective RT.")
c("RUBY / NRG-GY018", "Adding dostarlimab or pembrolizumab to carboplatin-paclitaxel improves PFS, with the largest benefit in dMMR tumours. In pMMR disease the gain is modest.")
c("KEYNOTE-775", "Lenvatinib-pembrolizumab improves OS after platinum in advanced endometrial cancer, including pMMR tumours. Toxicity (hypertension, fatigue, hypothyroidism) often needs dose reductions.")
c("Cervix chemoRT (Rose / Morris, 1999 NCI alert)", "Cisplatin-based chemoRT improves OS in locally advanced cervical cancer and is the global standard. Older RT techniques without image-guided brachytherapy were used, which modern practice has improved.")
c("EMBRACE-I", "MRI-guided adaptive brachytherapy gives excellent local control with low morbidity. It is non-randomised but large; access to MRI-based brachytherapy is limited in India.")
c("INTERLACE", "Six weeks of weekly carboplatin-paclitaxel before chemoRT improves OS in locally advanced cervical cancer. It is cheap and practical, though few stage III–IVA patients were included and it pre-dates IO.")
c("KEYNOTE-A18", "Pembrolizumab with chemoRT improves PFS and OS in high-risk locally advanced cervical cancer. Cost is a major barrier in India, where cervical cancer burden is high.")
c("GOG 240", "Adding bevacizumab to chemotherapy improves OS in recurrent/metastatic cervical cancer. Fistula risk, especially after pelvic RT, requires caution.")
c("KEYNOTE-826", "Pembrolizumab with chemotherapy ± bevacizumab improves OS in persistent/recurrent/metastatic cervical cancer. Benefit is mainly in PD-L1 CPS ≥1, which is most patients.")
c("SHAPE", "Simple hysterectomy is non-inferior to radical hysterectomy for low-risk early cervical cancer, with less urinary morbidity. Careful pre-operative imaging and selection are essential.")
c("LACC", "Minimally invasive radical hysterectomy had worse DFS and OS than open surgery for early cervical cancer, reversing practice. Surgeon experience and uterine manipulator use have been debated.")
c("JCOG1008", "Weekly cisplatin 40 mg/m² is non-inferior to 3-weekly 100 mg/m² in the postoperative high-risk setting, with less toxicity. Together with Noronha's trial, the choice depends on setting and patient fitness.")
c("PARSPORT", "Parotid-sparing IMRT reduces xerostomia and improves quality of life over conventional RT. It made IMRT the standard for head and neck RT.")
c("Sun / Zhang NPC GP induction", "GP induction before chemoRT improves OS in locoregionally advanced NPC. It comes from endemic EBV-related NPC in China; applicability to non-endemic populations is assumed.")
c("KEYNOTE-048", "Pembrolizumab ± chemotherapy improves OS over EXTREME in first-line R/M HNSCC. Monotherapy is not effective in CPS <1, so CPS guides choice.")
c("CheckMate 141", "Nivolumab improves OS over investigator's choice in platinum-refractory R/M HNSCC, with better quality of life. Response rates are low (~13%), but responses are durable.")
c("Patil (Tata) metronomic", "Low-dose nivolumab (40 mg) with metronomic chemotherapy improved OS in R/M HNSCC — a low-cost, practical option for India. It was single-centre and did not compare low dose with standard dose.")
c("KEYNOTE-689", "Perioperative pembrolizumab improves EFS in resectable locally advanced HNSCC, with benefit mainly in PD-L1-positive tumours. OS data are immature.")
c("EORTC/NCIC (Stupp)", "TMZ with RT improved OS in newly diagnosed GBM, especially in MGMT-methylated tumours. Patients over 70 were excluded, and the benefit in unmethylated tumours is small.")
c("Perry elderly GBM", "Adding TMZ to short-course RT improves OS in elderly GBM, especially MGMT-methylated tumours. It is a practical, tolerable regimen for older patients.")
c("EF-14 (TTFields)", "TTFields with TMZ improved OS in GBM after chemoRT. The open-label design without sham control, device burden and cost limit adoption.")
c("RTOG 9802 / EORTC 22033", "RT with PCV improves OS in high-risk low-grade glioma. Molecular analysis shows benefit is greatest in IDH-mutant tumours.")
c("RTOG 9402 / EORTC 26951", "RT with PCV improves OS in 1p/19q-codeleted anaplastic oligodendroglioma. It defined molecular markers as predictive in glioma.")
c("CATNON", "Adjuvant TMZ improves OS in 1p/19q non-codeleted anaplastic glioma, mainly in IDH-mutant tumours. Concurrent TMZ added no benefit.")
c("INDIGO", "Vorasidenib improves PFS and delays the need for RT or chemotherapy in grade 2 IDH-mutant glioma. OS and long-term neurocognitive benefits are not yet shown.")
c("Patchell (surgery + WBRT)", "Surgery plus WBRT improves OS and functional independence for a single brain metastasis. It pre-dates SRS, which is now an alternative.")
c("N0574 (Brown)", "SRS alone causes less cognitive decline than SRS + WBRT for 1–3 brain metastases, with similar OS. Higher intracranial recurrence without WBRT requires MRI surveillance.")
c("JLGK0901 (Yamamoto)", "SRS alone for 5–10 metastases gives non-inferior OS compared with 2–4 metastases. It is observational, so it supports but does not prove SRS for multiple metastases.")
c("NRG CC001", "Hippocampal-avoidance WBRT with memantine reduces cognitive decline compared with WBRT + memantine. It requires IMRT and careful planning.")
c("QUARTZ", "WBRT did not improve OS or quality of life in poor-prognosis NSCLC brain metastases. Supportive care alone is appropriate for these patients.")
c("IFM 2009", "Early ASCT after RVD improves PFS but not OS compared with RVD alone and ASCT at relapse. Deferring ASCT is an option for selected patients.")
c("GRIFFIN / PERSEUS", "Adding daratumumab to VRd induction, ASCT and maintenance improves PFS and MRD negativity. D-VRd is the new standard for transplant-eligible myeloma.")
c("MAIA", "Daratumumab with Rd improves PFS and OS in transplant-ineligible myeloma. Continuous therapy and infection risk require monitoring.")
c("CEPHEUS / IMROZ", "Quadruplet therapy (anti-CD38 + VRd) improves PFS in transplant-ineligible or deferred myeloma. Toxicity in frail elderly patients requires careful selection.")
c("CALGB 100104 / Myeloma XI", "Lenalidomide maintenance after ASCT improves OS. Second primary malignancies are a known risk.")
c("CARTITUDE-4", "Cilta-cel improves PFS and OS in lenalidomide-refractory myeloma after 1–3 lines. Early deaths, CRS and neurotoxicity, and limited access are concerns.")
c("MajesTEC-3", "Teclistamab with daratumumab improves PFS and OS in relapsed myeloma. Infection risk requires prophylaxis and IVIG.")
c("GELA LNH98-5 (R-CHOP)", "R-CHOP improved OS over CHOP in elderly DLBCL and became the global standard. Rituximab biosimilars have improved access in India.")
c("POLARIX", "Pola-R-CHP improves PFS over R-CHOP in intermediate/high-risk DLBCL, but not OS. Cost limits uptake.")
c("ZUMA-7 / TRANSFORM", "CAR-T improves EFS and OS over salvage chemotherapy and ASCT in early relapsed LBCL. Access, cost and toxicity limit use in India.")
c("HD10 / HD16 / RAPID", "PET-guided RT omission in early favourable HL slightly increases relapse but avoids RT late effects. Shared decisions based on age and RT field are key.")
c("RATHL", "Dropping bleomycin after negative interim PET reduces lung toxicity without compromising efficacy in advanced HL. PET-positive patients still do poorly.")
c("ECHELON-1", "A-AVD improves OS over ABVD in stage III–IV HL. Neuropathy and febrile neutropenia require G-CSF.")
c("HD21", "BrECADD improves PFS with less toxicity than eBEACOPP in advanced HL. It is suitable for fit younger patients.")
c("S1826", "Nivolumab-AVD improves PFS over brentuximab-AVD in advanced HL. OS data are awaited.")
c("PRIMA (FL)", "Rituximab maintenance improves PFS in advanced FL but not OS. Infection risk and cost must be considered.")
c("StiL / BRIGHT", "BR improves PFS with less toxicity than R-CHOP in indolent NHL and MCL. Prolonged lymphopenia increases infection risk.")
c("TRIANGLE", "Adding ibrutinib to induction and maintenance allows ASCT omission in younger fit MCL. OS data are awaited.")
c("CLL14 / ELEVATE-TN / RESONATE-2", "Targeted agents improve PFS over chemoimmunotherapy in untreated CLL. Choice between continuous BTKi and fixed-duration venetoclax-obinutuzumab depends on comorbidities and preference.")
c("Daunorubicin 90 vs 45 (E1900)", "Daunorubicin 90 mg/m² improves OS over 45 mg/m² in younger AML. NCRI AML17 suggested 60 mg/m² is equivalent to 90 mg/m².")
c("RATIFY", "Midostaurin with 7+3 improves OS in FLT3-mutated AML. Many patients proceeded to transplant, which may have contributed.")
c("VIALE-A", "Venetoclax with azacitidine improves OS in AML unfit for intensive chemotherapy. Myelosuppression and infection require monitoring.")
c("APL0406 (Lo-Coco)", "ATRA + ATO improves EFS over ATRA + chemotherapy in low/intermediate-risk APL. It is a chemotherapy-free cure for most patients.")
c("IRIS", "Imatinib transformed CML into a chronic disease with near-normal life expectancy. Generic imatinib is widely available in India.")
c("PhALLCON / GIMEMA LAL2116", "Ponatinib and chemo-free regimens achieve high MRD negativity in Ph+ ALL. Long-term outcomes are awaited.")
c("E1910", "Blinatumomab consolidation improves OS in MRD-negative B-ALL. Neurotoxicity and cost are concerns.")
c("CheckMate 067", "Nivo-ipi gives the longest OS in advanced melanoma, with ~50% alive at 10 years. Grade 3–4 toxicity in ~60% requires experienced management.")
c("RELATIVITY-047", "Nivolumab-relatlimab improves PFS over nivolumab alone with less toxicity than nivo-ipi. OS was not significantly improved.")
c("COMBI-d/v & COLUMBUS", "BRAF/MEK combinations improve OS over BRAFi alone in BRAF V600 melanoma. Resistance develops, so durability is less than IO.")
c("DREAMseq", "Starting with nivo-ipi gives better OS than starting with BRAF/MEK in BRAF V600 melanoma. Immunotherapy first is preferred.")
c("KEYNOTE-054 / CheckMate 238 / COMBI-AD", "Adjuvant therapy improves RFS in resected stage III melanoma. OS benefit is not proven.")
c("SWOG S1801", "Neoadjuvant pembrolizumab improves EFS over adjuvant pembrolizumab alone. Neoadjuvant IO is now preferred for resectable melanoma.")
c("NADINA", "Neoadjuvant nivo-ipi with response-adapted surgery improves EFS over upfront surgery and adjuvant nivolumab. It is a new standard.")
c("MSLT-II / DeCOG-SLT", "Completion lymph node dissection does not improve OS in sentinel node-positive melanoma. Ultrasound surveillance is standard.")
c("mRNA-4157 + pembrolizumab (KEYNOTE-942)", "Personalised neoantigen vaccine with pembrolizumab improves RFS in resected melanoma. It is phase 2; phase 3 (INTerpath-001) has since reported.")
c("Cemiplimab cSCC / Avelumab Merkel", "Immunotherapy gives high, durable response rates in advanced cSCC and Merkel cell carcinoma. Data are single-arm, and transplant recipients are at risk of rejection.")
c("ACOSOG Z9001 / SSG XVIII", "Three years of adjuvant imatinib improves OS over one year in high-risk GIST. Optimal duration beyond three years is under study.")
c("B2222 / EORTC 62005", "Imatinib 400 mg is standard for advanced GIST, with 800 mg for KIT exon 9 mutations. Resistance develops over time.")
c("INVICTUS / VOYAGER", "Ripretinib improves OS as fourth-line therapy in GIST. Avapritinib is effective for PDGFRA D842V.")
c("O'Sullivan NCIC SR2", "Preoperative RT causes less fibrosis and oedema than postoperative RT but more wound complications. Preoperative RT is preferred for extremity sarcoma.")
c("STRASS", "Preoperative RT did not improve abdominal recurrence-free survival in retroperitoneal sarcoma overall. Liposarcoma may benefit.")
c("EORTC 62012", "Doxorubicin + ifosfamide improves response but not OS over doxorubicin alone. The combination is used when response is needed for symptom control or surgery.")
c("EURAMOS-1", "Intensifying chemotherapy for poor responders did not improve outcomes in osteosarcoma. MAP remains standard.")
c("EURO EWING 2012 / rEECur", "VDC/IE improves OS over VIDE in Ewing sarcoma. Interval compression requires G-CSF.")
c("Hartsell RTOG 97-14", "A single 8 Gy fraction gives equal pain relief to 30 Gy/10 for bone metastases. Higher retreatment rates are acceptable for convenience.")
c("SC.24 (spine SBRT)", "SBRT improves complete pain response for spinal metastases. Fracture risk and technology requirements limit use.")
c("Patchell MSCC", "Surgery plus RT improves ambulation over RT alone for MSCC. Patient selection is key.")
c("SCORAD III", "A single 8 Gy fraction is non-inferior to 20 Gy/5 for ambulation in MSCC. It is appropriate for patients with short life expectancy.")
c("ORIOLE / STOMP", "Metastasis-directed therapy delays ADT in oligometastatic prostate cancer. Larger trials are needed.")
c("Navari olanzapine CINV", "Olanzapine 10 mg improves nausea control with HEC. Sedation is common; 5 mg may suffice.")
c("Hokusai VTE Cancer / SELECT-D / Caravaggio", "DOACs are non-inferior to LMWH for cancer-associated VTE. Higher GI bleeding with edoxaban and rivaroxaban in GI cancers requires caution.")
c("Denosumab vs zoledronic acid (Stopeck / Fizazi)", "Denosumab reduces skeletal events more than zoledronic acid. It does not improve OS, and hypocalcaemia and cost are concerns.")
c("ABCSG-18 / Early Breast EBCTCG bisphosphonates", "Adjuvant bisphosphonates reduce fractures and recurrence in postmenopausal early breast cancer. Osteonecrosis of the jaw is rare but serious.")
PATCH["CheckMate 8HW"] = {"strengths": ["Superior PFS for nivo-ipi vs chemotherapy (first line) and vs nivolumab alone (all lines)", "Large randomised trial in a biomarker-defined population"]}
